// Map the selected catalog_lines (sent by the app in the webhook body) to the Hermes item
// shape and hand them over as ONE payload — one request for the whole selection, the way
// it worked before f03db96 (client, 2026-07-31).
//
// Returning a SINGLE n8n item is what makes the HTTP node fire exactly once: n8n runs an
// HTTP node once per input item, so one item in = one POST out.
//
// EAN: the catalog stores a 13-digit EAN, but Hermes wants the barcode WITHOUT the
// catalog's leading zero — a 13-digit EAN starting with 0 is sent as 12 digits
// (0075678581519 -> 075678581519). Only the first zero is dropped; a non-zero 13-digit EAN
// or an already-12-digit one is sent unchanged (Hermes accepts 12 or 13).
const hermesEan = (v) => {
  const s = String(v ?? '').replace(/[^0-9]/g, '');
  if (!s) return null;
  return (s.length === 13 && s[0] === '0') ? s.slice(1) : s;
};

const lines = $('Webhook').first().json.body?.lines ?? [];

return [{ json: {
  items: lines.map(l => ({
    title: l.title ?? null,
    author: l.artist ?? null,
    releaseDate: l.release_date ?? null,
    format: l.format ?? null,
    ean: hermesEan(l.ean),
    calculationGroup: l.calculation_group ?? null,
    supplierCode: l.supplier_code ?? null,
  })),
  // Carried alongside the payload so Map Sent can tie a response row back to a catalog
  // line. Kept in the SAME ORDER as items.
  meta: lines.map(l => ({ line_id: l.id, ean: l.ean ?? null })),
} }];

// Map Sent — write the Hermes MblaID back as hermes_id, and mark as sent ONLY the lines
// Hermes actually confirmed.
//
// Response (confirmed from live sends) is an array holding one object per request:
//   { message, return_description, return_value, status }
//   * status 1 -> the request was processed. return_value is a JSON *string* array of
//                 [{ EAN: '075678581540', MblaID: 70463 }, ...].
//   * status 0 -> one or more items were NOT processed. return_value is pipe-delimited
//                 text that NAMES them ("Item with EAN = ... already exists ... Skipping
//                 insertion.") and carries no MblaID.
//
// WHY THIS IS CAREFUL. /api/productsCatalogue is all-or-nothing per request: a batch
// containing even one already-known EAN comes back status 0, and the genuinely-new items
// in that same batch are NOT inserted either. That is exactly why f03db96 had split this
// into one POST per line. Sending one payload again is the client's call, so the guard
// moves here: a line is marked sent ONLY when Hermes confirmed it — it came back with an
// MblaID, or it was named as already existing, or the whole request reported status 1.
// Anything else keeps sent_at null and its empty Hermes badge in the app, so it stays
// visible and can be re-sent on its own.

// 1) Gather the response object(s) however n8n surfaced the top-level array.
const responses = [];
for (const it of $('Hermes POST Catalogue').all()) {
  const j = it.json;
  if (Array.isArray(j)) responses.push(...j);
  else if (j && Array.isArray(j.body)) responses.push(...j.body);
  else if (j) responses.push(j);
}

const normEan = v => String(v ?? '').replace(/[^0-9]/g, '').replace(/^0+/, '');
const idByEan = new Map();   // EAN -> MblaID (or null when Hermes gave none)
const alreadyThere = new Set(); // EANs Hermes reported as existing
let requestProcessed = false;   // any response with status 1

for (const r of responses) {
  if (!r) continue;
  if (Number(r.status) === 1) requestProcessed = true;

  let rv = r.return_value;
  if (rv == null) continue;

  if (typeof rv === 'string') {
    const s = rv.trim();
    if (s.startsWith('[') || s.startsWith('{')) {
      try { rv = JSON.parse(s); } catch (e) { continue; }
    } else {
      // Plain text: it names the EANs it skipped because they already exist. Those rows
      // ARE in Hermes, so they count as confirmed.
      for (const hit of (s.match(/EAN\s*=?\s*'?\d{8,14}/gi) || [])) {
        const d = hit.match(/\d{8,14}/);
        if (d) alreadyThere.add(normEan(d[0]));
      }
      continue;
    }
  }

  for (const row of (Array.isArray(rv) ? rv : [rv])) {
    const ean = row && (row.EAN ?? row.ean);
    if (ean == null) continue;
    const id = row && (row.MblaID ?? row.mblaId ?? row.mbla_id ?? row.id);
    // Hermes has been seen to answer MblaID 0: the row was processed, there is simply no
    // id to keep. Confirm the line, but never store '0' as a hermes_id.
    idByEan.set(normEan(ean), (id != null && Number(id) !== 0) ? String(id) : null);
  }
}

// 2) Current hermes_id per line, straight from the webhook payload (select *), so an id a
//    historical row already had is never clobbered. '0' is NOT an id (2fe882a) — some rows
//    were written with it before that rule existed, so it is treated as absent here too
//    rather than being carefully preserved.
const existingById = new Map(
  ($('Webhook').first().json.body?.lines ?? []).map(l => {
    const cur = l.hermes_id == null ? null : String(l.hermes_id);
    return [String(l.id), (cur === '' || Number(cur) === 0) ? null : cur];
  })
);

// 3) One writeback row per CONFIRMED line.
const meta = $('Prepare Items').first().json.meta ?? [];
const out = [];
const unconfirmed = [];
for (const m of meta) {
  const key = normEan(m.ean);
  const gotId = idByEan.has(key);
  const confirmed = gotId || alreadyThere.has(key) || requestProcessed;
  if (!confirmed) { unconfirmed.push(m.ean || m.line_id); continue; }
  out.push({ json: {
    id: m.line_id,
    hermes_id: (gotId ? idByEan.get(key) : null) ?? existingById.get(String(m.line_id)) ?? null,
  } });
}

if (unconfirmed.length) {
  console.log('Hermes did not confirm ' + unconfirmed.length + ' of ' + meta.length +
    ' line(s); they stay unsent and can be re-sent: ' + unconfirmed.join(', '));
}

// Nothing confirmed at all -> fail loudly rather than answer the app with a silent success.
if (!out.length) {
  const r = responses[0] || {};
  throw new Error('Hermes confirmed none of the ' + meta.length +
    ' item(s) in this batch — nothing was marked as sent. ' +
    String(r.return_description || r.message || r.return_value || '').slice(0, 300));
}

return out;
